#!/usr/bin/env -S uv run --script
# Synced from bootstrap: macos/tools/tailscale/tasks/tailscale-daemon.py. Do not edit this file.
# The next sync writes it again, and each change in this file is lost.
# /// script
# requires-python = ">=3.14"
# dependencies = []
# ///
# MISE description="Start tailscaled as a root brew service (prompts for sudo)"
# MISE hide=true
# MISE dir="~"
# MISE tools={uv="latest", python="3.14"}

# Run by `updateall`. The formula itself is
# mise's; only the daemon goes through `brew services`, because tailscaled needs
# root for the utun interface and mise has no privileged services on macOS.
# Only starts when tailscaled is not running: `sudo brew services start`
# re-bootstraps the daemon even when it is up, which drops the tunnel.

import os
import subprocess
import sys

sys.dont_write_bytecode = True
sys.path.insert(0, os.path.expanduser("~/.config/mise/tasks/_scripts"))
import helpers  # noqa: E402


def main():
  if subprocess.run(["pgrep", "-x", "tailscaled"], check=False, stdout=subprocess.DEVNULL).returncode == 0:
    helpers.print_header("tailscaled is already running.")
    sys.exit(0)
  helpers.print_header("Starting tailscaled (root brew service) ...")
  rc = subprocess.run(["sudo", "brew", "services", "start", "tailscale"], check=False).returncode
  sys.exit(128 - rc if rc < 0 else rc)


if __name__ == "__main__":
  main()
